import { LitElement, html, css, nothing, type PropertyValues } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import './sw-icon';
import type { IconName } from './sw-icon';
import type { StateKind } from './sw-badge';
import { fitSchedule, fitTextElement } from './fit-text';

/**
 * Stat tile as on the boards: icon in a soft-blue square, big value, label, green/amber sub-label.
 *
 * Owner 2026-09-29 (overview tiles):
 * - `layout`: `cards` (default - the tall tile, icon above) or `compact` (a rectangle: the icon at the inline-start
 *   side, the value and label beside it on one line - a long label wraps to a second line, then ellipsis - and one
 *   line of secondary text). The screen resolves `ui.tile_layout` (api/tile-layout.ts) and passes it here. The compact
 *   sizes are the `--sw-kpi-compact-*` custom properties (the knobs: styles/tile-knobs.ts, DEVICE_THEMES.md §9).
 * - a tile can be a real control: `href` makes it a link (a navigation), `action` a button (it opens something on the
 *   same screen; `expanded` is its aria-expanded). The hit area is the whole tile, a native <a> / <button> laid over
 *   it, named by the tile's own text; the host's `title` carries the full text for a label cut by the ellipsis.
 */
@customElement('sw-kpi')
export class SwKpi extends LitElement {
  @property() label = '';
  @property() value = '';
  @property() detail = '';
  @property() icon: IconName = 'info';
  @property({ reflect: true }) tone: StateKind = 'neutral';
  @property() badge = '';
  /** MULTIBUILDING-HOME-2330: a quiet scope tag ("אתר" / "בניין א") riding the tile's top corner opposite the badge; empty = none. */
  @property() tag = '';
  @property({ reflect: true }) layout: 'cards' | 'compact' = 'cards';
  /** A navigation: the whole tile is this link. */
  @property() href = '';
  /** A button: the whole tile is a button (the host's own click event carries the press). */
  @property({ type: Boolean }) action = false;
  @property({ type: Boolean }) expanded = false;
  /** Compact layout: the icon sits at the END of the text block (the left side in Hebrew) instead of the start. */
  @property({ type: Boolean, reflect: true, attribute: 'icon-end' }) iconEnd = false;
  /** Words added to the control's accessible name ("הצג ושלוט", "פתח"). */
  @property() hint = '';

  static styles = css`
    :host {
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 12px 14px;
      background: var(--sw-surface);
      border: 1px solid var(--sw-border);
      border-radius: var(--sw-r-md);
      box-shadow: var(--sw-shadow-1);
      min-inline-size: 0;
      position: relative;
    }
    .icon {
      display: grid;
      place-items: center;
      inline-size: 30px;
      block-size: 30px;
      border-radius: var(--sw-r-sm);
      background: var(--sw-accent-soft);
      color: var(--sw-accent);
      flex: none;
    }
    :host([tone='error']) .icon,
    :host([tone='offline']) .icon {
      background: var(--sw-danger-soft);
      color: var(--sw-danger);
    }
    :host([tone='stale']) .icon,
    :host([tone='partial']) .icon {
      background: var(--sw-stale-soft);
      color: var(--sw-stale);
    }
    /* POLISH-295: a screen may colour a counter that has something on by its kind (--sw-kpi-on-bg / --sw-kpi-on-fg, tokens only) */
    /* POLISH-CLASSIC-DOMUS-297 (audit finding 3, owner "no green outside status meaning"): "all is well" no longer paints the tile's
       icon green - the healthy state is the quiet one; its word below (the detail line) still carries the status colour. A screen
       that colours a counter by its kind keeps doing so through --sw-kpi-on-bg / --sw-kpi-on-fg. */
    :host([tone='live']) .icon {
      background: var(--sw-kpi-on-bg, var(--sw-surface-3));
      color: var(--sw-kpi-on-fg, var(--sw-text-2));
    }
    .txt {
      min-inline-size: 0;
    }
    .value,
    .label {
      display: block;
    }
    /* R5-LIVE-297 (sw-kpi size hook, like --sw-kpi-label-lines): a host may ask for a display numeral; unset = the old 20 px / 700 */
    .value {
      font-size: var(--sw-kpi-value-fs, var(--sw-fs-2xl));
      font-weight: var(--sw-kpi-value-fw, var(--sw-fw-bold));
      line-height: 1.1;
      letter-spacing: -0.02em;
      font-variant-numeric: tabular-nums;
      color: var(--sw-heading);
    }
    .label {
      font-size: var(--sw-fs-xs);
      color: var(--sw-text-2);
      margin-block-start: 2px;
    }
    .detail {
      font-size: var(--sw-fs-xs);
      font-weight: var(--sw-fw-medium);
      color: var(--sw-success-text);
      margin-block-start: 1px;
      font-variant-numeric: tabular-nums;
    }
    :host([tone='stale']) .detail,
    :host([tone='partial']) .detail {
      color: var(--sw-warning-text);
    }
    :host([tone='error']) .detail,
    :host([tone='offline']) .detail {
      color: var(--sw-danger-text); /* the ink of the status, not its bare dot colour (3.8:1 on white) */
    }
    :host([tone='neutral']) .detail {
      color: var(--sw-text-3);
    }
    .badge {
      position: absolute;
      inset-inline-end: 10px;
      inset-block-start: 10px;
      background: var(--sw-badge-bg);
      color: var(--sw-badge-fg);
      font-size: var(--sw-fs-2xs);
      font-weight: var(--sw-fw-semibold);
      border-radius: var(--sw-r-pill);
      padding: 1px 7px;
      white-space: nowrap;
      font-variant-numeric: tabular-nums;
    }

    /* ---- compact: a rectangle, the icon beside the text (knobs: --sw-kpi-compact-*) ---- */
    :host([layout='compact']) {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr);
      align-items: center;
      column-gap: var(--sw-kpi-compact-gap, 10px);
      row-gap: 0;
      box-sizing: border-box;
      min-block-size: var(--sw-kpi-compact-min-block, 60px);
      padding-block: var(--sw-kpi-compact-pad-block, 8px);
      padding-inline: var(--sw-kpi-compact-pad-inline, 12px);
    }
    :host([layout='compact']) .icon {
      inline-size: var(--sw-kpi-compact-icon, 32px);
      block-size: var(--sw-kpi-compact-icon, 32px);
    }
    /* owner 2026-09-30 (home screen): the icon at the end of the text block - the left side in Hebrew */
    :host([layout='compact'][icon-end]) {
      grid-template-columns: minmax(0, 1fr) auto;
    }
    :host([layout='compact'][icon-end]) .icon {
      order: 2;
    }
    /* the value above its label: the text block stays narrow enough for a small tile */
    :host([layout='compact'][icon-end]) .value,
    :host([layout='compact'][icon-end]) .label {
      display: block;
      margin: 0;
    }
    :host([layout='compact'][icon-end]) .label {
      line-height: 1.25;
    }
    /* the value and the label on one line; a long label wraps once, then ellipsis (the full text is the host's title).
       POLISH-CLASSIC-DOMUS-297 second pass (break-ui, P4/P6): the VALUE never wraps ("1284 / 2047" broke over two lines and pushed the
       label out of the clamp, so the label vanished) - only the label is clamped; the figures are tabular */
    :host([layout='compact']) .line {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      column-gap: 6px;
      min-inline-size: 0;
      line-height: 1.25;
    }
    :host([layout='compact']) .value,
    :host([layout='compact']) .label {
      margin: 0;
    }
    :host([layout='compact']) .value {
      flex: 0 1 auto;
      min-inline-size: 0;
      max-inline-size: 100%;
      overflow: hidden;
      white-space: nowrap;
      font-variant-numeric: tabular-nums;
      font-size: var(--sw-kpi-compact-value-fs, 17px);
      line-height: 1.2;
    }
    /* a value wider than its tile first shrinks (fit-text.ts, to ~72 %), and only at that floor breaks at its spaces ("53928 /
       49392"), never inside a number; it never runs over the icon */
    :host([layout='compact']) .value[data-fit='wrap'] {
      white-space: normal;
      overflow: visible;
      overflow-wrap: normal;
      line-height: 1.1;
    }
    :host([layout='compact']) .label {
      flex: 1 1 4em;
      min-inline-size: 0;
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--sw-kpi-label-lines, 2);
      line-clamp: var(--sw-kpi-label-lines, 2);
      overflow: hidden;
      overflow-wrap: anywhere;
      font-size: var(--sw-fs-xs);
    }
    /* icon at the end: the value above its label, the label one clamped line (the tile's height as before) */
    :host([layout='compact'][icon-end]) .line {
      flex-direction: column;
      align-items: flex-start;
    }
    /* HOMEFABLE-297 (sw-kpi size hook): the host may ask for two label lines (--sw-kpi-label-lines) - the home's counters do */
    :host([layout='compact'][icon-end]) .label {
      display: -webkit-box;
      -webkit-line-clamp: var(--sw-kpi-label-lines, 1);
      line-clamp: var(--sw-kpi-label-lines, 1);
      inline-size: 100%;
      flex: 0 1 auto; /* the row layout's 4em basis is a HEIGHT in this column - the label is as tall as its clamped lines */
    }
    :host([layout='compact'][icon-end]) .value {
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
    }
    :host([layout='compact']) .detail {
      margin-block-start: 1px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    /* review M6: the badge rides the tile's top corner - it never takes a column from the value and the label */
    .tag {
      position: absolute;
      inset-inline-start: 10px;
      inset-block-start: -7px;
      z-index: 2;
      pointer-events: none;
      max-inline-size: calc(100% - 20px);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      padding: 0 6px;
      border-radius: var(--sw-r-pill);
      background: var(--sw-surface-3-solid, var(--sw-surface-3));
      color: var(--sw-text-2);
      font-size: var(--sw-fs-2xs);
      font-weight: var(--sw-fw-semibold);
      line-height: 14px;
    }
    :host([layout='compact']) .badge {
      inset-block-start: -7px;
      inset-inline-end: 8px;
      z-index: 2;
      pointer-events: none;
    }

    /* ---- a tile that is a control: the native link / button covers it ---- */
    .hit {
      position: absolute;
      inset: 0;
      z-index: 1;
      margin: 0;
      padding: 0;
      border: 0;
      border-radius: inherit;
      background: transparent;
      color: inherit;
      font: inherit;
      cursor: pointer;
      -webkit-tap-highlight-color: transparent;
    }
    .hit:focus-visible {
      outline: var(--sw-focus-w) solid var(--sw-focus);
      outline-offset: 2px;
    }
    :host([interactive]) {
      transition: border-color var(--sw-t-hover) var(--sw-ease-color), box-shadow var(--sw-t-hover) var(--sw-ease-color), transform var(--sw-t-press) var(--sw-ease);
    }
    /* the hover convention of the shared components: only under a pointer that hovers (a tapped tile kept its lift on a phone) */
    @media (hover: hover) and (pointer: fine) {
      :host([interactive]:hover) {
        border-color: var(--sw-border-strong);
        box-shadow: var(--sw-shadow-2);
      }
    }
    :host([interactive]:active) {
      transform: scale(calc(1 - (1 - var(--sw-press-scale)) / 3));
    }
    :host([interactive][data-expanded]) {
      border-color: var(--sw-border-strong);
      box-shadow: var(--sw-shadow-2);
    }
    :host([interactive][data-expanded]) {
      border-color: var(--sw-accent);
    }
  `;

  /** Everything the tile says, in reading order: the control's accessible name and the host's tooltip. */
  private get words(): string {
    return [`${this.value} ${this.label}`.trim(), this.detail, this.badge].filter(Boolean).join(' · ');
  }

  /** Pass 2 (break-ui): the compact value is fitted to its tile on every render and every resize (one measure per frame). */
  private fitSlot = { raf: 0 };
  private ro: ResizeObserver | null = null;
  private fitValue() {
    if (this.layout !== 'compact') return;
    fitSchedule(() => {
      const v = this.renderRoot.querySelector<HTMLElement>('.value');
      if (v) fitTextElement(v);
    }, this.fitSlot);
  }
  connectedCallback() {
    super.connectedCallback();
    if (typeof ResizeObserver !== 'undefined') {
      this.ro = new ResizeObserver(() => this.fitValue());
      this.ro.observe(this);
    }
  }
  disconnectedCallback() {
    super.disconnectedCallback();
    this.ro?.disconnect();
    this.ro = null;
  }
  protected updated() {
    this.fitValue();
  }

  protected willUpdate(changed: PropertyValues<this>) {
    const interactive = !!this.href || this.action;
    this.toggleAttribute('interactive', interactive);
    this.toggleAttribute('data-expanded', this.action && this.expanded);
    if (changed.has('value') || changed.has('label') || changed.has('detail') || changed.has('badge')) this.title = this.words;
  }

  render() {
    const name = [this.words, this.hint].filter(Boolean).join(' · ');
    // review low: the control carries the whole text as its name - the visible text is not read a second time
    const interactive = !!this.href || this.action;
    return html`
      <div class="icon" aria-hidden=${interactive ? 'true' : nothing}><sw-icon .name=${this.icon} size=${16}></sw-icon></div>
      <div class="txt" aria-hidden=${interactive ? 'true' : nothing}>
        <div class="line"><span class="value">${this.value}</span> <span class="label">${this.label}</span></div>
        ${this.detail ? html`<div class="detail">${this.detail}</div>` : nothing}
      </div>
      ${this.badge ? html`<span class="badge" aria-hidden=${interactive ? 'true' : nothing}>${this.badge}</span>` : nothing}
      ${this.tag ? html`<span class="tag" data-kpi-tag aria-hidden="true">${this.tag}</span>` : nothing}
      ${this.href
        ? html`<a class="hit" href=${this.href} aria-label=${name}></a>`
        : this.action
          ? html`<button class="hit" type="button" aria-haspopup="dialog" aria-expanded=${String(this.expanded)} aria-label=${name}></button>`
          : nothing}
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sw-kpi': SwKpi;
  }
}
